package net.minecraft.game.world.terrain.generate.feature;

import net.minecraft.game.item.ItemStack;

/**
 * A chest planned by a structure's constructor, flushed during populate.
 * Filled sequentially (slots 0..n) rather than random slots — cosmetic only.
 */
public class SpecialBlockInStructureChest extends SpecialBlockInStructure {
	/** Loot rolls for this chest, generated by Treasure.rollLoot(). */
	public final ItemStack[] contents;
	/** Port of WorldGenHollowHillInterior.fillWithBlocksDownwads: while the column
	 *  below is air or water and above y1, replace it with cobblestone. */
	public final boolean cobblePillar;

	public SpecialBlockInStructureChest(int x, int y, int z, int blockID, int metadata,
			ItemStack[] contents, boolean cobblePillar) {
		super(x, y, z, blockID, metadata);
		this.contents = contents;
		this.cobblePillar = cobblePillar;
	}
}
